// Hankuk University of Foreign Studies, Seoul campus (한국외국어대학교 서울캠퍼스, 서울 동대문구 이문동). Data is generated by
// scripts/campuses/hufs/build-package.mjs from the pilot (pilot/hufs-seoul, round 3): the 15 models of active-models.json (본관 and
// 사이버관 detailed, the rest generic), all destructible (no hospital, religious or heritage building: the protected list is empty),
// a baked ground drawn with the pilot's ground look (terrain-profile.json groundLook = src/engine/ground-look.js, pkg.ground.baked.look),
// the preview's own planting (same trees), the pilot's landscape models and the non-destructible context (이문동, 외대앞역, 천장산)
// fading into the haze. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, HF_PLACEMENTS, HF_BUILDING_BASE, HF_HEIGHT_GRIDS, HF_HEIGHT_RANGE_M, HF_ENV_IDS, HF_LOOK, HF_DISPLAY, HF_PROVENANCE } from './data.js';
import { HF_FOOTPRINTS } from './footprints.js';
import { HF_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(HF_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/hufs/${file}`, import.meta.url).href;
const HAZE = HF_DISPLAY.haze, FADE = HF_DISPLAY.fade;

export const HUFS = Object.freeze({
  id: 'hufs',
  meta: Object.freeze({ school: '한국외국어대학교', campus: '서울캠퍼스', short: '외대', modelNoun: '외대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: HF_PLACEMENTS,
  approvedCount: HF_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['main', 'cyber', 'library', 'globeeDorm', 'history'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'main',
  // Start: from over the south-east (이문로 side) looking north-west along the gate -> 본관 axis: 정문 and the 진입로 at the bottom,
  // 사이버관 / 교수회관 on the left, the 대운동장 in the middle, the 미네르바 광장 and 본관's tower at the far end.
  // R3b (2026-10-22, Codex HU-R3-04): the R3 box (E -120..150, N -80..60 m, 28 m high) put the camera ~190 m up (431 m at 390 px) and the
  // 래미안 towers east of the gate filled the right side. Box now = the campus core only, E -100..120, N -80..24 m, 16 m high (world units:
  // metres x 0.5, z = -N); azimuth 1.0 kept. Checked by projecting the buildings with src/camera.js in Node before the browser run:
  // campus buildings' screen share 0.35 -> 0.58 (1280) / 0.21 -> 0.29 (390), tall context (> 30 m) 0.79 -> 0.46 / 0.26 -> 0.19, gate and
  // 본관 tower top inside the HUD-free band at both widths.
  // Start closer on 본관 and the 역사기념관 lawn (user 10-26: the old wide frame started too far, worst on phones).
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600
    ? { min: [-64, 0, -32], max: [-34, 8, 2], azimuth: 1.0 }
    : { min: [-78, 0, -42], max: [-2, 8, 24], azimuth: 1.0 }; } }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: HF_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: HF_HEIGHT_GRIDS, buildingBase: HF_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30 + floor-link / photo level evidence, pilot/hufs-seoul); not a survey' }),
  environment: Object.freeze({ provenance: HF_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: HF_ENV_IDS, castShadow: Object.freeze([]), look: HF_LOOK,
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/hufs-seoul preview ground + planting + landscape + context, baked' }),
  }),
  // Protected: none at HUFS (every model destructible). Kept so a later pilot decision only needs a rebuild; the manifest exists only
  // when the list is not empty (src/main.js loads protected models only when models.length > 0).
  protected: Object.freeze({
    ...(HF_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: HF_PROTECTED,
  }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js): none on the context.
  hazardTape: Object.freeze({ footprints: HF_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: fog 900..2600 m, hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-300, 330, 220) to (0, 10, 0) -> halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 450, far: 1300 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-150, 165, 110]), shadowSpan: 220 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: HF_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default HUFS;
